  // Prefix anlam grupları: [önek, anlamı, grup, örnekler]
  const G = {n:"Negative", r:"Reversative and privative", d:"Degree and size", a:"Attitude", t:"Time and order", s:"Space, direction and location", i:"Iterative"};
